// GENERATED by scripts/sync_nodes.py from the live n8n workflow — do not edit here.
// Edit in n8n, then re-run the script; the workflow is the system of record.
// Node: Parse response

// Parse the model's JSON response, score + sort deterministically, render HTML.
// JSON mode guarantees valid JSON, NOT our shape — and the provider docs admit
// the API may occasionally return empty content. Never throw here: zero picks is
// a normal day, and Has picks? stops the run cleanly.
const resp = $input.first().json;

let txt = '';
let finishReason = '';
try {
  const ch = (resp.choices && resp.choices[0]) || {};
  finishReason = ch.finish_reason || '';
  txt = (ch.message && ch.message.content) ? String(ch.message.content) : '';
} catch (e) {}

// finish_reason 'length' with empty content means the token budget ran out --
// usually the thinking tokens ate it. Surfaced in the output so a zero-pick day
// caused by truncation is distinguishable from a genuinely empty selection.
const truncated = (finishReason === 'length' && !txt.trim());

// The router can land on a provider with json_mode: false (config/providers.yaml),
// where the gateway silently DROPS response_format and the model answers inside a
// markdown fence or with a sentence around the object. Cut to the outermost braces
// before parsing; the single-provider DeepSeek path never needed this.
const jsonSlice = (s) => {
  const t = String(s).trim().replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '').trim();
  const a = t.indexOf('{'), b = t.lastIndexOf('}');
  return (a >= 0 && b > a) ? t.slice(a, b + 1) : t;
};

let parsed = { picks: [] };
if (txt.trim()) {
  try {
    const p = JSON.parse(jsonSlice(txt));
    if (p && Array.isArray(p.picks)) parsed = p;
  } catch (e) { parsed = { picks: [], parseError: String(e), raw: txt.slice(0, 500) }; }
}

const build = $('Build request').first().json;
const cands = build.cands || [];
const runDate = build.runDate;
const hashtagStats = build.hashtagStats || [];

const bool = (v) => v === true || v === 'true' || v === 1;

let items = (parsed.picks || []).map(p => {
  const idx = Number(p && p.index);
  if (!Number.isInteger(idx) || idx < 0 || idx >= cands.length) return null;
  const c = cands[idx] || {};
  const line = String((p && p.line) || '').trim();
  if (!line) return null;
  const score = (bool(p.csoportos) ? 100 : 0)
    + ((bool(p.csoportos) && bool(p.oktatos)) ? 50 : 0)
    + (bool(p.felnott) ? 20 : 0);
  return {
    line: line,
    url: String(c.url || '').split('?')[0],
    platform: c.platform || '',
    imageUrl: c.image || '',
    hashtags: c.hashtags || '',
    engagement: (c.likes || 0) + (c.comments || 0),
    csoportos: bool(p.csoportos), oktatos: bool(p.oktatos), felnott: bool(p.felnott),
    score: score
  };
}).filter(x => x && x.url && x.line);

// dedupe by url, keep highest score
const byUrl = {};
for (const it of items) {
  if (!byUrl[it.url] || it.score > byUrl[it.url].score) byUrl[it.url] = it;
}
items = Object.values(byUrl);

items.sort((a, b) => (b.score - a.score) || (b.engagement - a.engagement));
const top = items.slice(0, 5);

let html = '';
top.forEach((x, i) => {
  let block = '<p style="margin:0 0 20px 0">' + (i + 1) + '. ' + x.line
    + ' (<a href="' + x.url + '">' + x.platform + '</a>)';
  if (x.hashtags) block += '<br><span style="color:#888;font-size:13px">' + x.hashtags + '</span>';
  if (x.imageUrl) block += '<br><img src="' + x.imageUrl + '" alt="" style="max-width:180px;border-radius:8px;display:block;margin:8px 0">';
  block += '</p>';
  html += block;
});

// Hashtag delta block — only when at least one hashtag has a comparable
// previous row, so the very first run does not print a table of dashes.
const huNum = (n) => String(n).replace(/\B(?=(\d{3})+(?!\d))/g, ' ');
const comparable = hashtagStats.filter(h => !h.first && h.delta !== null);
if (comparable.length) {
  const rows = hashtagStats.slice().sort((a,b) => ((b.delta == null ? -1 : b.delta) - (a.delta == null ? -1 : a.delta))).map(h => {
    let val;
    if (h.first || h.delta == null) val = '&mdash; (első mérés)';
    else if (h.delta === 0) val = '&mdash;';
    else val = huNum(h.delta) + (h.spanDays > 1 ? (' (' + h.spanDays + ' nap alatt)') : '');
    return '<tr><td style="padding:2px 12px 2px 0">#' + h.hashtag + '</td>'
      + '<td style="padding:2px 0;text-align:right">' + val + '</td></tr>';
  }).join('');
  html += '<hr style="border:0;border-top:1px solid #eee;margin:28px 0 14px 0">'
    + '<p style="margin:0;color:#888;font-size:13px">Új poszt tegnap óta (Instagram):</p>'
    + '<table style="border-collapse:collapse;font-size:13px;color:#888;margin-top:6px">' + rows + '</table>';
}

const picks = top.map(x => ({
  url: x.url, platform: x.platform, line: x.line,
  score: x.score, csoportos: x.csoportos, oktatos: x.oktatos, felnott: x.felnott
}));

return [ { json: { picks: picks, html: html, runDate: runDate, candidateCount: build.candidateCount, hashtagStats: hashtagStats, finishReason: finishReason, truncated: truncated } } ];
